input.sparql:
SELECT ?sensor ?setpoint WHERE {
  ?zone a brick:Zone ;
        rdfs:label "Core_mid" .
  { ?zone brick:hasPoint ?sensor . ?sensor a brick:Zone_Air_Temperature_Sensor . }
  UNION
  { ?zone brick:hasPoint ?setpoint . ?setpoint a brick:Zone_Air_Temperature_Setpoint . }
}

SELECT ?point ?class WHERE {
  <http://buildgraph.org/BG_large_office_2004_0000#Zone_F3_Z01> brick:hasPoint ?point .
  ?point a ?class .
  FILTER(?class IN (brick:Zone_Air_Temperature_Sensor, brick:Zone_Air_Temperature_Setpoint, brick:Temperature_Setpoint))
}
